#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here

    int t;
    cin >> t;
    
    while(t--)
    {
        int m, n;
        cin >> m >> n;
        int days=0;
        
        vector<int> pos(n);
        
        
        for(int i=0; i<n; i++)
        {
            cin >> pos[i];
        }
        
        vector<int> temp = pos;
        
        sort(pos.begin(), pos.end());
        
        int minv = pos[0];
        
        days+=minv-1;
        
        for(auto& val : pos)
        val-=(minv-1);
        
        // 
        // for(int val : pos)
        // cout << val << " ";
        
        
        int maxv=INT_MIN;
        for(int i=0; i<n-1; i++)
        {
            if (pos[i+1]-pos[i]-1>maxv) maxv = pos[i+1]-pos[i]-1;
        }
        
        if(m+1-pos[n-1]-1>maxv) maxv = m+1-pos[n-1]-1;
        
        days+=maxv;
        
        // if (maxv>minv-1) days-=minv-1;
        
        // cout << days << endl;
        
        sort(temp.begin(), temp.end());
        int days2=0;
        int smaxv = m-temp[n-1];
        
        
        // cout << m << " " << temp[n-1] << endl;
        // cout << smaxv << endl;
        
        days2+=smaxv;
        
        for(auto& v : temp)
        v+=smaxv;
        
        int tempd, maxd=INT_MIN;
        
        for(int i=n-1; i>0; i--)
        {
            if (temp[i]-temp[i-1]-1>maxd) maxd = temp[i]-temp[i-1]-1;
        }
        
        maxd = max(maxd, temp[0]-1);
        
        // cout << maxd << endl;
        
        days2+=maxd;
        // if (maxd>smaxv)
        // days2-=smaxv;
        
        
        // cout << days2 << endl;

        int fres = min(days, days2);
        
        cout << fres << endl;
        
    }

}
